/** Tolerance of the sample study (the page's default USL / LSL). */
export const GAGE_SAMPLE_TOL = { USL: 72, LSL: 70 } as const

/**
 * True when the input is exactly the sample study: same measurements, same
 * tolerance. Free visitors can run the full analysis on it (open example);
 * any other data needs Pro. Used by the page and checked again by
 * /api/gage-rr on the server.
 */
export function isGageSampleInput(measurements: unknown, USL: unknown, LSL: unknown): boolean {
  if (USL !== GAGE_SAMPLE_TOL.USL || LSL !== GAGE_SAMPLE_TOL.LSL) return false
  if (!Array.isArray(measurements) || measurements.length !== GAGE_SAMPLE_DATA.length) return false
  return GAGE_SAMPLE_DATA.every((parts, a) => {
    const ma = measurements[a]
    return Array.isArray(ma) && ma.length === parts.length && parts.every((trials, p) => {
      const mp = ma[p]
      return Array.isArray(mp) && mp.length === trials.length && trials.every((v, k) => mp[k] === v)
    })
  })
}
